let html = "";
let texto2 = "";

// =======================================
// FUNCIÓN HELPER PARA OBTENER ITEMS DE FORMA SEGURA
// =======================================
const obtenerItemsSeguro = (nombreNodo) => {
  try {
    const items = $items(nombreNodo);
    return items || [];
  } catch (error) {
    console.log(`⚠️ Nodo "${nombreNodo}" no encontrado o desactivado`);
    return [];
  }
};

// =======================================
// Obtener información del formulario
// =======================================
const formularioItems = obtenerItemsSeguro("Obtener campos del formulario");
const formulario = formularioItems.length > 0 ? formularioItems[0].json : {};

// Parsear inf_parametros
let parametros = {};
if (formulario.inf_parametros) {
    try {
        parametros = JSON.parse(formulario.inf_parametros);
    } catch (e) {
        parametros = {};
    }
}

// =======================================
// Obtener Información General
// =======================================
const infoItems = obtenerItemsSeguro("Información General");
const info = infoItems.length > 0 ? infoItems[0].json : {};
const ig = info.informacion_general || {};

// =======================================
// ENCABEZADO HTML
// =======================================
html += `<h1>📘 ${formulario.inf_nombre || "TÍTULO NO ESPECIFICADO"}</h1>`;
html += `<p><b>Guion teórico para infografía interactiva</b></p>`;
html += `<hr><br><br>`;

html += `<h2>1. INFORMACIÓN GENERAL</h2><br>`;

html += `<p><b>Título del recurso:</b><br>${formulario.inf_nombre || "No especificado"}</p><br>`;
html += `<p><b>Tipo de recurso:</b><br>${ig.tipo_recurso || "No especificado"}</p><br>`;
html += `<p><b>Nivel educativo:</b><br>${ig.nivel_educativo || "No especificado"}</p><br>`;
html += `<p><b>Área:</b><br>${ig.area || "No especificado"}</p><br>`;

html += `<p><b>Palabras clave:</b><br>`;
html += Array.isArray(ig.palabras_clave) ? ig.palabras_clave.join(", ") : "No especificadas";
html += `</p><br>`;

html += `<p><b>Resumen académico</b><br>${info.resumen_academico || "No disponible"}</p><br>`;

if (Array.isArray(info.objetivos_aprendizaje) && info.objetivos_aprendizaje.length) {
    html += `<p><strong>Objetivos de aprendizaje</strong></p><ul>`;
    info.objetivos_aprendizaje.forEach(obj => {
        html += `<li>${obj}</li>`;
    });
    html += `</ul>`;
}

html += `<br>`;

if (Array.isArray(info.competencias) && info.competencias.length) {
    html += `<p><strong>Competencias</strong></p><ul>`;
    info.competencias.forEach(comp => {
        html += `<li>${comp}</li>`;
    });
    html += `</ul>`;
}

html += `<br><hr><br><br>`;

// =======================================
// PROMPTS POR TEXTO BASE
// =======================================
const itemsPrompts = obtenerItemsSeguro("Generar prompts");
const promptsPorTexto = {};

itemsPrompts.forEach(item => {
    const meta = item.json?.metadata || {};
    const textoBase = (meta.texto_base || "").trim();

    if (textoBase) {
        promptsPorTexto[textoBase] =
            item.json?.openrouter?.messages?.[0]?.content?.[0]?.text
            || meta.original_prompt
            || "";
    }
});

// =======================================
// CONTENIDO POR SLIDE
// =======================================
const temasItems = obtenerItemsSeguro("Transformar a la estructura original1");
let itemsTemas = temasItems.slice(1);
let slideIndex = 1;

itemsTemas.forEach(item => {
    const tema = item.json || {};

    (tema.subtemas || []).forEach(sub => {
        (sub.contenido || []).forEach(parrafo => {

            const texto = parrafo.trim();
            const promptImagen = promptsPorTexto[texto];

            html += `<h3>Slide ${slideIndex} | Guión Teórico Detallado</h3><br>`;
            html += `<p><b>Sección:</b> ${tema.nombre || "Sin nombre"}<br>`;
            html += `<b>Subsección:</b> ${sub.nombre || "Sin nombre"}</p><br>`;

            html += `<p><b>Contenido del Slide</b></p>`;
            html += `<p>${texto}</p><br>`;

            if (promptImagen) {
                html += `<p><b>Prompt para generar imagen:</b></p>`;
                html += `<p>${promptImagen}</p><br>`;
            }

            html += `<hr><br><br><br>`;
            slideIndex++;
        });
    });
});

// =======================================
// TRIVIA (CONTADOR GLOBAL)
// =======================================
const itemsPreguntas = obtenerItemsSeguro("Dividir preguntas y respuestas");

html += `<h2>🧠 Trivia — ${formulario.inf_nombre || "Trivia"}</h2><br>`;

const triviaPorNivel = { básico: [], intermedio: [], avanzado: [] };
itemsPreguntas.forEach(item => {
    const n = (item.json?.dificultad || "").toLowerCase();
    if (triviaPorNivel[n]) triviaPorNivel[n].push(item.json);
});

let contadorGlobal = 1;

function imprimirNivelHTML(nombre, preguntas, icono) {
    if (!preguntas.length) return;

    const nombreFormateado = nombre.charAt(0).toUpperCase() + nombre.slice(1);
    html += `<h3>${icono} Nivel ${nombreFormateado} (${preguntas.length})</h3><br>`;

    preguntas.forEach(p => {
        const pregunta = (p.pregunta || "").replace(/<\/?p>/g, "").trim();

        html += `<p><b>${contadorGlobal}. ${pregunta}</b></p><br>`;

        const letras = ["A", "B", "C", "D"];
        let correcta = "";

        (p.respuestas || []).forEach((r, i) => {
            html += `<p>${letras[i]}) ${r.texto || ""}</p>`;
            if (r.correcta) correcta = letras[i];
        });

        html += `<br><p><b>Respuesta correcta:</b> ${correcta}<br>`;
        html += `<b>Justificación:</b> ${p.justificacion || "No disponible"}<br>`;
        html += `<b>Nivel:</b> ${nombreFormateado}</p>`;

        html += `<br><br>`;
        contadorGlobal++;
    });
}

imprimirNivelHTML("básico", triviaPorNivel.básico, "🟢");
imprimirNivelHTML("intermedio", triviaPorNivel.intermedio, "🟡");
imprimirNivelHTML("avanzado", triviaPorNivel.avanzado, "🔴");

// =======================================
// SECCIÓN FINAL VACÍA
// =======================================
html += `<hr><br><br>`;
html += `<h2>📚 Referencias bibliográficas — ${formulario.inf_nombre || "TÍTULO NO ESPECIFICADO"}</h2>`;

// =======================================
// TEXTO PLANO (SIN CAMBIOS)
// =======================================
texto2 += `Título: ${formulario.inf_nombre || "Sin título"}\n\n`;

itemsTemas.forEach(item => {
    const tema = item.json || {};
