const salida = [];

for (const item of items) {
  if (!item.json.output) continue;

  let raw = item.json.output;

  // 🧹 Limpiar backticks y markdown
  raw = raw
    .replace(/```json\s*/gi, '')
    .replace(/```\s*/g, '')
    .trim();

  let parsed;

  try {
    // Intento 1: parsear directo
    parsed = JSON.parse(raw);
  } catch (e1) {
    try {
      // Intento 2: buscar el último corchete válido y cerrar el JSON
      const lastBracket = raw.lastIndexOf(']');
      if (lastBracket !== -1) {
        const truncated = raw.substring(0, lastBracket + 1);
        parsed = JSON.parse(truncated);
      } else {
        throw new Error('No se encontró cierre de array');
      }
    } catch (e2) {
      try {
        // Intento 3: cerrar manualmente objetos y arrays incompletos
        let fixed = raw;

        // Contar llaves y corchetes abiertos/cerrados
        const openBraces = (fixed.match(/{/g) || []).length;
        const closeBraces = (fixed.match(/}/g) || []).length;
        const openBrackets = (fixed.match(/\[/g) || []).length;
        const closeBrackets = (fixed.match(/\]/g) || []).length;

        // Cerrar lo que falta
        for (let i = 0; i < openBraces - closeBraces; i++) {
          fixed += '}';
        }
        for (let i = 0; i < openBrackets - closeBrackets; i++) {
          fixed += ']';
        }

        parsed = JSON.parse(fixed);
      } catch (e3) {
        // Si todo falla, registrar error y continuar
        console.error(`Error parseando item: ${e3.message}`);
        console.error(`Preview: ${raw.substring(0, 200)}...`);

        salida.push({
          json: {
            error: 'JSON truncado o inválido',
            preview: raw.substring(0, 500),
            message: e3.message
          }
        });
        continue;
      }
    }
  }

  // Extraer preguntas del JSON parseado
  // Puede venir como array directo o dentro de una propiedad
  let preguntas = [];

  if (Array.isArray(parsed)) {
    preguntas = parsed;
  } else if (parsed.trivia && Array.isArray(parsed.trivia)) {
    preguntas = parsed.trivia;
  } else if (parsed.preguntas && Array.isArray(parsed.preguntas)) {
    preguntas = parsed.preguntas;
  }

  // Agregar cada pregunta válida
  for (const pregunta of preguntas) {
    // Validar estructura mínima
    if (pregunta.pregunta && Array.isArray(pregunta.respuestas)) {
      salida.push({
        json: pregunta
      });
    }
  }
}

// Si no se obtuvo nada, retornar advertencia
if (salida.length === 0) {
  return [{
    json: {
      warning: 'No se pudieron extraer preguntas',
      items_procesados: items.length
    }
  }];
}

return salida;

